export default function build({ THREE, kit, traits, ui, hands }) {
  const root = new THREE.Group();
  root.name = 'Cactus Dash';
  const floor = 0.033, runnerZ = 0.09;
  const mat = {
    frame: kit.material('paintedMetal', { color: '#254d50', wear: 0.22 }),
    edge: kit.material('brass', { roughness: 0.48 }),
    sand: kit.material('sand', { colors: ['#bd814d', '#e6bc7c', '#f4d49a'] }),
    path: kit.material('sand', { colors: ['#d79f61', '#efc98e'] }),
    rock: kit.material('stone', { colors: ['#aa553a', '#ce7950', '#e5a875'] }),
    dino: kit.material('plastic', { color: '#39a593', roughness: 0.66 }),
    belly: kit.material('plastic', { color: '#bce5bb', roughness: 0.7 }),
    dark: kit.material('rubber', { color: '#153b3e' }),
    white: kit.material('ceramic', { color: '#fff2cc' }),
    cactus: kit.material('paintedMetal', { color: '#4d8851', wear: 0.15 }),
    rib: kit.material('plastic', { color: '#79ad65' }),
    flower: kit.material('plastic', { color: '#f39165' }),
    lamp: kit.material('light', { color: '#b8ffd0', glow: 1.3 }),
    button: kit.material('paintedMetal', { color: '#e69b43', wear: 0.13 })
  };
  function mesh(geo, material, x = 0, y = 0, z = 0, parent = root) {
    const m = new THREE.Mesh(geo, material);
    m.position.set(x, y, z);
    parent.add(m);
    return m;
  }
  function box(w, h, d, material, x, y, z, parent = root, radius = 0.001) {
    return mesh(kit.roundedBox(w, h, d, radius), material, x, y, z, parent);
  }

  root.add(kit.shadow(0.29, 0.28));
  const scenery = new THREE.Group();
  root.add(scenery);
  box(0.44, 0.025, 0.45, mat.frame, 0, 0.014, -0.005, scenery, 0.014);
  box(0.425, 0.006, 0.435, mat.edge, 0, 0.027, -0.005, scenery, 0.01);
  box(0.414, 0.007, 0.424, mat.sand, 0, 0.0295, -0.005, scenery, 0.009);
  box(0.122, 0.001, 0.405, mat.path, 0, floor, -0.008, scenery, 0.005);

  const bolts = [], lights = [];
  for (const x of [-0.212, 0.212]) {
    for (let z = -0.2; z <= 0.2; z += 0.05) bolts.push([x, 0.028, z]);
    box(0.004, 0.004, 0.38, mat.dark, x, 0.031, -0.012, scenery);
  }
  for (const x of [-0.067, 0.067]) {
    for (let z = -0.185; z < 0.19; z += 0.037) lights.push([x, floor + 0.001, z]);
  }
  scenery.add(kit.instances(new THREE.CylinderGeometry(0.0017, 0.0017, 0.0015, 8), mat.edge, bolts));
  scenery.add(kit.instances(kit.roundedBox(0.004, 0.001, 0.012, 0.001), mat.white, lights));

  // A miniature desert, with cut-stone mesas and scattered mineral fragments.
  for (const side of [-1, 1]) {
    for (let i = 0; i < 3; i++) {
      const x = side * (0.12 + i * 0.025);
      const z = -0.155 + i * 0.033;
      const h = 0.025 + (2 - i) * 0.012;
      const outline = [
        [-0.021, 0], [-0.021, h * 0.5], [-0.014, h * 0.5],
        [-0.014, h * 0.86], [-0.008, h * 0.86], [-0.008, h],
        [0.011, h], [0.011, h * 0.7], [0.018, h * 0.7], [0.024, 0]
      ];
      mesh(kit.extrude(outline, 0.032, { bevel: 0.001 }), mat.rock, x, floor, z, scenery);
      box(0.027, 0.002, 0.033, mat.sand, x, floor + h * 0.47, z, scenery);
    }
  }
  const pebbles = [];
  for (let i = 0; i < 38; i++) {
    const side = i % 2 ? -1 : 1;
    pebbles.push({
      position: [side * (0.082 + ((i * 17) % 100) * 0.0011), floor + 0.002, -0.19 + ((i * 43) % 340) * 0.001],
      rotation: [0, i * 1.9, 0],
      scale: [0.003 + (i % 3) * 0.0015, 0.002 + (i % 2) * 0.002, 0.004]
    });
  }
  scenery.add(kit.instances(new THREE.DodecahedronGeometry(1, 0), mat.rock, pebbles));
  kit.merge(scenery);

  // The voxel T. rex: stepped tail, broad snout, tiny arms and alternating feet.
  const dinosaur = new THREE.Group();
  dinosaur.name = 'Voxel dinosaur';
  dinosaur.position.set(0, floor, runnerZ);
  dinosaur.rotation.y = -0.48;
  root.add(dinosaur);
  const body = new THREE.Group();
  dinosaur.add(body);
  box(0.035, 0.039, 0.044, mat.dino, 0, 0.042, 0.006, body);
  box(0.031, 0.025, 0.025, mat.dino, 0, 0.062, -0.006, body);
  box(0.044, 0.032, 0.043, mat.dino, 0, 0.08, -0.02, body);
  box(0.04, 0.021, 0.025, mat.dino, 0, 0.073, -0.047, body);
  box(0.034, 0.008, 0.036, mat.belly, 0, 0.058, -0.038, body);
  box(0.022, 0.027, 0.003, mat.belly, 0, 0.039, -0.017, body);
  const tails = [
    [0.028, 0.024, 0.026, 0.029, 0.035],
    [0.021, 0.018, 0.022, 0.033, 0.056],
    [0.014, 0.012, 0.021, 0.039, 0.074],
    [0.008, 0.008, 0.015, 0.044, 0.09]
  ];
  for (const [w, h, d, y, z] of tails) box(w, h, d, mat.dino, 0, y, z, body);
  for (const s of [-1, 1]) {
    box(0.006, 0.013, 0.008, mat.white, s * 0.023, 0.084, -0.026, body);
    box(0.002, 0.007, 0.005, mat.dark, s * 0.0263, 0.084, -0.028, body);
    box(0.003, 0.004, 0.004, mat.dark, s * 0.016, 0.078, -0.060, body);
    box(0.008, 0.012, 0.009, mat.dino, s * 0.022, 0.041, -0.016, body);
    box(0.008, 0.006, 0.015, mat.belly, s * 0.022, 0.036, -0.022, body);
    for (let t = 0; t < 3; t++) {
      box(0.003, 0.004, 0.003, mat.white, s * 0.018, 0.063, -0.035 - t * 0.008, body);
    }
  }
  kit.merge(body);
  const legs = [];
  for (const s of [-1, 1]) {
    const leg = new THREE.Group();
    leg.position.set(s * 0.014, 0.026, 0.008);
    dinosaur.add(leg);
    box(0.016, 0.022, 0.018, mat.dino, 0, -0.007, 0, leg);
    box(0.016, 0.009, 0.029, mat.dino, 0, -0.0215, -0.007, leg);
    for (let j = 0; j < 2; j++) {
      box(0.004, 0.003, 0.005, mat.white, -0.004 + j * 0.008, -0.024, -0.022, leg);
    }
    kit.merge(leg);
    legs.push(leg);
  }

  function makeCactus(index) {
    const group = new THREE.Group();
    group.name = 'Rushing cactus ' + (index + 1);
    root.add(group);
    box(0.021, 0.055, 0.022, mat.cactus, 0, 0.0275, 0, group);
    for (const s of [-1, 1]) {
      const y = s < 0 ? 0.023 : 0.034;
      box(0.017, 0.011, 0.015, mat.cactus, s * 0.017, y, 0, group);
      box(0.011, 0.025, 0.015, mat.cactus, s * 0.025, y + 0.008, 0, group);
      box(0.003, 0.041, 0.0015, mat.rib, s * 0.005, 0.027, 0.0115, group);
    }
    box(0.013, 0.004, 0.013, mat.flower, 0, 0.057, 0, group);
    box(0.005, 0.007, 0.005, mat.white, 0, 0.060, 0, group);
    const needles = [];
    for (let i = 0; i < 5; i++) {
      needles.push([-0.007, 0.009 + i * 0.009, 0.013]);
      needles.push([0.007, 0.013 + i * 0.008, 0.013]);
    }
    group.add(kit.instances(kit.roundedBox(0.002, 0.001, 0.003, 0.0003), mat.white, needles));
    kit.merge(group);
    return { group, z: -0.19 - index * 0.29, passed: false };
  }
  const obstacles = [makeCactus(0), makeCactus(1), makeCactus(2)];

  // Moving grit gives the runway motion even between obstacles.
  const grit = kit.instances(
    kit.roundedBox(0.003, 0.001, 0.008, 0.0005), mat.rock,
    Array.from({ length: 24 }, () => [0, 0, 0])
  );
  root.add(grit);
  const matrix = new THREE.Matrix4();
  const dust = kit.particles({ count: 22, box: [0.06, 0.017, 0.055], color: '#f5d8a3', size: 0.003 });
  dust.position.set(0, floor + 0.009, runnerZ + 0.026);
  root.add(dust);
  const pulse = kit.ring(0.022, 0.027, { colors: ['#f3edb7', '#7ce1ba'], opacity: 0.7 });
  pulse.position.set(0, floor + 0.002, runnerZ);
  root.add(pulse);

  let mode = 'demo', score = 0, best = 0, lives = 3;
  let jumpY = 0, velocity = 0, invincible = 0, feedback = 0, distance = 0;
  let startPress = 0, jumpPress = 0;
  let panel;
  function status(text, tone = 'neutral') { panel.set('state', text, tone); }
  function hud() {
    panel.set('score', score + '  |  ' + lives + ' lives');
    panel.set('best', 'Best ' + best + ' - ' + Math.floor(distance) + ' m');
  }
  function start() {
    mode = 'play'; score = 0; lives = 3; distance = 0;
    jumpY = 0; velocity = 0; invincible = 0; startPress = 0.22;
    obstacles.forEach((o, i) => { o.z = -0.19 - i * 0.29; o.passed = false; });
    hud();
    status('Go! Pinch to jump.', 'good');
    panel.set('start', 'Restart');
    panel.set('pause', 'Pause');
  }
  function jump() {
    jumpPress = 0.16;
    if (mode === 'demo' || mode === 'over') start();
    if (mode !== 'play' || jumpY > 0.001) return;
    velocity = 0.44;
    feedback = 0.32;
    status('Jump!', 'good');
  }
  function control(x, label, material, onPress) {
    const g = new THREE.Group();
    g.name = label + ' button';
    g.position.set(x, floor, 0.151);
    root.add(g);
    mesh(kit.lathe([[0, 0], [0.032, 0], [0.034, 0.006], [0.03, 0.012], [0, 0.012]], 32), mat.dark, 0, 0, 0, g);
    const cap = mesh(kit.lathe([[0, 0], [0.027, 0], [0.027, 0.008], [0.022, 0.014], [0, 0.014]], 32), material, 0, 0.01, 0, g);
    const tag = kit.card(label, { width: 0.067 });
    tag.position.set(0, 0.034, 0.014);
    g.add(tag);
    traits(g, { onPress });
    return cap;
  }
  const startCap = control(-0.145, 'START', mat.dino, start);
  const jumpCap = control(0.145, 'JUMP', mat.button, jump);

  panel = kit.panel(ui, {
    width: 0.36, position: [0, 0.32, -0.22], rotationY: 0,
    eyebrow: 'CACTUS DASH', title: 'Tiny Rex Run',
    items: [
      { text: 'Pinch either hand to jump over the cacti.' },
      { stat: '0  |  3 lives', label: 'cacti cleared', id: 'score' },
      { status: 'Ready? Keep your feet off the spines.', id: 'state', tone: 'neutral' },
      { text: 'Best 0 - 0 m', id: 'best' },
      { buttons: [
        { label: 'Start', id: 'start', onPress: start },
        { label: 'Pause', id: 'pause', onPress() {
          if (mode === 'play') { mode = 'paused'; status('Paused'); panel.set('pause', 'Resume'); }
          else if (mode === 'paused') { mode = 'play'; status('Run!', 'good'); panel.set('pause', 'Pause'); }
        } }
      ] }
    ]
  });
  root.add(panel.object3D);

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);
      if ((hands.left.tracked && hands.left.pinched) || (hands.right.tracked && hands.right.pinched)) jump();
      startPress = Math.max(0, startPress - dt);
      jumpPress = Math.max(0, jumpPress - dt);
      startCap.position.y = startPress > 0 ? 0.006 : 0.01;
      jumpCap.position.y = jumpPress > 0 ? 0.006 : 0.01;
      const running = mode !== 'paused';
      const demo = mode === 'demo' || mode === 'over';
      const speed = 0.155 + Math.min(score, 35) * 0.0025;
      if (running) {
        if (demo && jumpY <= 0.001) {
          for (let i = 0; i < obstacles.length; i++) {
            const ahead = runnerZ - obstacles[i].z;
            if (ahead > 0 && ahead < speed * 0.32) { velocity = 0.44; break; }
          }
        }
        jumpY += velocity * dt;
        velocity -= 1.05 * dt;
        if (jumpY < 0) {
          if (velocity < -0.1) feedback = 0.22;
          jumpY = 0; velocity = 0;
        }
        invincible = Math.max(0, invincible - dt);
        feedback = Math.max(0, feedback - dt);
        distance += mode === 'play' ? speed * dt * 20 : 0;
        for (let i = 0; i < obstacles.length; i++) {
          const o = obstacles[i];
          o.z += speed * dt;
          if (o.z > 0.21) {
            let back = 0;
            for (let j = 0; j < obstacles.length; j++) back = Math.min(back, obstacles[j].z);
            o.z = back - 0.265 - Math.random() * 0.055;
            o.passed = false;
          }
          o.group.position.set(0, floor, o.z);
          o.group.visible = o.z > -0.202 && o.z < 0.197;
          if (mode === 'play' && !o.passed && Math.abs(o.z - runnerZ) < 0.026 && jumpY < 0.052 && invincible === 0) {
            lives--; invincible = 1.25; feedback = 0.4; o.passed = true;
            status(lives ? 'Ouch! Keep jumping.' : 'Run over! Try to beat ' + best + '.', lives ? 'poor' : 'bad');
            hud();
            if (!lives) { mode = 'over'; panel.set('start', 'Play again'); }
          }
          if (!o.passed && o.z > runnerZ + 0.029) {
            o.passed = true;
            if (mode === 'play') {
              score++; best = Math.max(best, score);
              hud();
              status(score % 5 === 0 ? 'Faster! ' + score + ' cleared.' : 'Clear!', 'good');
            }
          }
        }
      }
      dinosaur.position.y = floor + jumpY;
      dinosaur.rotation.z = jumpY > 0 ? -0.055 : Math.sin(time * 15) * 0.025;
      dinosaur.visible = invincible <= 0 || Math.floor(time * 14) % 2 === 0;
      for (let i = 0; i < legs.length; i++) {
        legs[i].rotation.x = jumpY > 0 ? (i ? 0.55 : -0.45) : Math.sin(time * 16 + i * Math.PI) * 0.48;
      }
      dust.visible = running && jumpY < 0.012;
      dust.rotation.y = time * 0.4;
      pulse.visible = feedback > 0;
      pulse.scale.setScalar(1 + (0.4 - feedback) * 3);
      for (let i = 0; i < 24; i++) {
        const z = ((time * speed + i * 0.018) % 0.39) - 0.2;
        const x = ((i * 13) % 9 - 4) * 0.012;
        matrix.makeTranslation(x, floor + 0.0015, z);
        grit.setMatrixAt(i, matrix);
      }
      grit.instanceMatrix.needsUpdate = true;
    }
  };
}
